#include "gnss_time.h"
#include <string.h>
#include <stdlib.h>
static int leap(int y){return(y%4==0&&y%100!=0)||y%400==0;}
static uint32_t epoch_utc(int y,int m,int d,int hh,int mm,int ss){static const int md[]={31,28,31,30,31,30,31,31,30,31,30,31};uint32_t days=0;for(int yy=1970;yy<y;yy++)days+=365+leap(yy);for(int mo=1;mo<m;mo++)days+=md[mo-1]+(mo==2&&leap(y));days+=(uint32_t)(d-1);return days*86400u+(uint32_t)hh*3600u+(uint32_t)mm*60u+(uint32_t)ss;}
static float dm_to_deg(const char*s,char hemi){if(!s||!*s)return 0.0f;double v=strtod(s,0);int deg=(int)(v/100.0);double min=v-deg*100.0;double out=deg+min/60.0;if(hemi=='S'||hemi=='W')out=-out;return(float)out;}
bool gnss_rmc_fix(const char *line,size_t len,gnss_fix_t*out){if(!line||!out||len<20||line[0]!='$')return false;char tmp[160];if(len>=sizeof tmp)len=sizeof tmp-1;memcpy(tmp,line,len);tmp[len]=0;char *fields[20]={0};size_t n=0;char *p=tmp;while(p&&n<20){fields[n++]=p;char*c=strchr(p,',');if(!c)break;*c=0;p=c+1;}if(n<10||!strstr(fields[0],"RMC")||strlen(fields[1])<6||fields[2][0]!='A'||strlen(fields[9])<6)return false;int hh=(fields[1][0]-'0')*10+fields[1][1]-'0',mm=(fields[1][2]-'0')*10+fields[1][3]-'0',ss=(fields[1][4]-'0')*10+fields[1][5]-'0';int d=(fields[9][0]-'0')*10+fields[9][1]-'0',mo=(fields[9][2]-'0')*10+fields[9][3]-'0',yy=(fields[9][4]-'0')*10+fields[9][5]-'0';int y=yy>=80?1900+yy:2000+yy;if(hh>23||mm>59||ss>60||d<1||d>31||mo<1||mo>12)return false;out->epoch=epoch_utc(y,mo,d,hh,mm,ss);out->latitude=dm_to_deg(fields[3],fields[4][0]);out->longitude=dm_to_deg(fields[5],fields[6][0]);out->speed_mps=(float)(strtod(fields[7],0)*0.514444);out->valid=true;return true;}
bool gnss_rmc_epoch(const char *line,size_t len,uint32_t*out){gnss_fix_t f={0};if(!out||!gnss_rmc_fix(line,len,&f))return false;*out=f.epoch;return true;}
